import sys

def main():
    N, A, B = map(int, sys.stdin.read().split())

    if A > B or N == 1:
        if A == B:
            print(1)
        else:
            print(0)
    else:
        min_sum = (N - 1) * A + B
        max_sum = (N - 1) * B + A
        print(max_sum - min_sum + 1)

if __name__ == "__main__":
    main()
"}

