import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    A = []
    for _ in range(N):
        A.append(next(it))

    B = []
    for _ in range(M):
        B.append(next(it))

    # Check all possible positions
    for i in range(N - M + 1):
        for j in range(N - M + 1):
            # Check if B matches starting at (i, j)
            match = True
            for k in range(M):
                if A[i + k][j:j + M] != B[k]:
                    match = False
                    break
            if match:
                print("Yes")
                return

    print("No")

solve()
"}

