import sys

def longest_palindromic_subsequence(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1]

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    t = int(data[0])
    index = 1
    for _ in range(t):
        n = int(data[index])
        index += 1
        s = data[index]
        index += 1
        if len(s) != n:
            # Not sure if this happens, but just in case
            continue
        lps = longest_palindromic_subsequence(s)
        print(len(s) - lps)

if __name__ == "__main__":
    solve()
"}

