n, x = map(int, input().split())
arr = list(map(int, input().split()))

from collections import defaultdict

# Count frequencies
freq = defaultdict(int)
for num in arr:
    freq[num] += 1

# For x = 0, count combinations of same numbers
if x == 0:
    answer = 0
    for count in freq.values():
        answer += count * (count - 1) // 2
else:
    # For x > 0, count pairs of complementary numbers but avoid double counting
    answer = 0
    seen = set()
    for num, count in freq.items():
        if num in seen:
            continue
        target = num ^ x
        if target in freq:
            if num == target:
                # Pair of same numbers
                answer += count * (count - 1) // 2
                seen.add(num)
            else:
                # Pair with different numbers
                if target not in seen:
                    answer += count * freq[target]
                    seen.add(num)
                    seen.add(target)

print(answer)
"}

