{"code": "import sys
import math

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    T = int(data[0])
    out_lines = []
    idx = 1
    for _ in range(T):
        a = int(data[idx])
        b = int(data[idx+1])
        c = int(data[idx+2])
        idx += 3
        # Compute gcd(a,b,c)
        g_ab = math.gcd(a, b)
        g_abc = math.gcd(g_ab, c)
        if g_abc != 1:
            out_lines.append("NO")
            continue
        # Check Pythagorean
        max_val = max(a, b, c)
        if max_val == a:
            if a * a == b * b + c * c:
                out_lines.append("YES")
            else:
                out_lines.append("NO")
        elif max_val == b:
            if b * b == a * a + c * c:
                out_lines.append("YES")
            else:
                out_lines.append("NO")
        else:  # max_val == c
            if c * c == a * a + b * b:
                out_lines.append("YES")
            else:
                out_lines.append("NO")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

