    N = int(data[idx]); idx += 1
    segments = []
    for _ in range(N):
        x1 = int(data[idx]); idx += 1
        y1 = int(data[idx]); idx += 1
        x2 = int(data[idx]); idx += 1
        y2 = int(data[idx]); idx += 1
        segments.append((x1, y1, x2, y2))

    while True:
        best_y = -1.0
        lowest_x = -1
        lowest_y = -1
        for (x1, y1, x2, y2) in segments:
            if x1 <= X <= x2:
                # compute y at X
                dx = x2 - x1
                dy = y2 - y1
                y_segment = y1 + ((X - x1) * dy) / dx
                if y_segment > best_y:
                    best_y = y_segment
                    if y1 < y2:
                        lowest_x = x1
                        lowest_y = y1
                    else:
                        lowest_x = x2
                        lowest_y = y2

        if best_y == -1.0:
