        if n in memo:
            return memo[n]
        sell = n
        # Break into parts
        part1 = compute(n // 2, memo)
        part2 = compute(n // 3, memo)
        part3 = compute(n // 4, memo)
        break_val = part1 + part2 + part3
        res = max(sell, break_val)
        memo[n] = res
        return res

    for n in numbers:
        memo = {}
        answer = compute(n, memo)
        print(answer)

if __name__ == '__main__':
