    # For each query, find max balanced remainder
    for _ in range(Q):
        q = int(next(it))
        max_remainder = -q // 2
        for card in cards:
            remainder = card % q
            if remainder > q // 2:
                remainder -= q
            if remainder > max_remainder:
                max_remainder = remainder
        print(max_remainder)

