import sys

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    # If n == 2 and both are the same color, impossible
    if n == 2:
        if s[0] == s[1]:
            print(-1)
        else:
            # We can flip to make them both same, but we can't change anything
            # because we only flip pairs and we have one of each
            print(-1)
        return

    # For n > 2, if there's at least one B and at least one W, we can always do it
    # We'll try to make all blocks the same color

    ops = []
    s = list(s)

    # Find the rightmost pair that are both the same
    def find_pair(s):
        for i in range(n - 2, -1, -1):
            if s[i] == s[i+1]:
                return i + 1  # 1-indexed
        return -1

    while True:
        i = find_pair(s)
        if i == -1:
            break
        ops.append(i)
        s[i-1] = 'W' if s[i-1] == 'B' else 'B'
        s[i] = 'W' if s[i] == 'B' else 'B'

    # Check if all same
    if all(x == 'B' for x in s) or all(x == 'W' for x in s):
        print(len(ops))
        print(' '.join(map(str, ops)))
    else:
        print(-1)

if __name__ == '__main__':
    solve()
