import math

def cross(o, a, b):
    """Cross product of OA and OB vectors."""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def area(polygon):
    """Compute the area of the polygon using shoelace formula."""
    n = len(polygon)
    result = 0.0
    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % n]
        result += (x1 * y2 - x2 * y1)
    return abs(result) / 2.0

def distance(a, b):
    """Compute Euclidean distance between points a and b."""
    return math.hypot(a[0] - b[0], a[1] - b[1])

def point_line_distance(p, a, b):
    """Compute distance from point p to line segment ab."""
    if a == b:
        return distance(p, a)
    # Distance from point to line
    d = abs((b[0] - a[0]) * (a[1] - p[1]) - (b[1] - a[1]) * (a[0] - p[0]))
    # Check if projection lies on segment
    if cross(a, b, p) < 0:
        return distance(p, a)
    if cross(b, a, p) < 0:
        return distance(p, b)
    return d

def point_in_triangle(p, a, b, c):
    """Check if point p is inside triangle abc (not on the edges)."""
    d1 = cross(a, b, c)
    d2 = cross(b, c, a)
    d3 = cross(c, a, b)
    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)
    return not (has_neg and has_pos)

def closest_point_on_segment(p, a, b):
    """Find the closest point on segment ab to point p."""
    if a == b:
        return a
    if cross(b, a, p) < 0:
        return a
    if cross(a, b, p) < 0:
        return b
    # Projection
    ax = a[0] - p[0]
    ay = a[1] - p[1]
    bx = b[0] - p[0]
    by = b[1] - p[1]
    t = (ax * ax + ay * ay) / (ax * bx + ay * by)
    t = max(0.0, min(1.0, t))
    return (a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1]))

def min_max_equal_area_chords(polygon):
    """Find minimum and maximum length chords that split polygon into two equal areas."""
    n = len(polygon)
    area_total = area(polygon)
    area_half = area_total / 2.0

    min_length = float('inf')
    max_length = float('-inf')

    # Try all pairs of vertices
    for i in range(n):
        for j in range(i + 1, n):
            a = polygon[i]
            b = polygon[j]
            if a == b:
                continue

            # Check if line ab splits the area
            # For each point in the polygon, check which side of line ab it's on
            left_area = 0.0
            right_area = 0.0
            for k in range(n):
                pk = polygon[k]
                if k == i:
                    left_area += distance(a, b)
                elif k == j:
                    right_area += distance(a, b)
                else:
                    # Check which side of line ab point pk is on
                    d = cross(a, b, pk)
                    if d > 0:
                        left_area += distance(a, b)
                    elif d < 0:
                        right_area += distance(a, b)

            # For a convex polygon, if both left and right have area > 0, the line splits it
            if left_area > 0.0 and right_area > 0.0:
                min_length = min(min_length, distance(a, b))
                max_length = max(max_length, distance(a, b))

    # Also check chords that go through vertices and along edges
    for i in range(n):
        a = polygon[i]
        b = polygon[(i + 1) % n]
        if a == b:
            continue

        # Check if line ab splits the area
        left_area = 0.0
        right_area = 0.0
        for k in range(n):
            pk = polygon[k]
            if k == i:
                left_area += distance(a, b)
            elif k == (i + 1) % n:
                right_area += distance(a, b)
            else:
                d = cross(a, b, pk)
                if d > 0:
                    left_area += distance(a, b)
                elif d < 0:
                    right_area += distance(a, b)

        if left_area > 0.0 and right_area > 0.0:
            min_length = min(min_length, distance(a, b))
            max_length = max(max_length, distance(a, b))

    return min_length, max_length

