    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def area(polygon):
    n = len(polygon)
    result = 0.0
    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % n]
        result += (x1 * y2 - x2 * y1)
    return abs(result) / 2.0

def distance(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])

def point_line_distance(p, a, b):
    if a == b:
        return distance(p, a)
    d = abs((b[0] - a[0]) * (a[1] - p[1]) - (b[1] - a[1]) * (a[0] - p[0]))
    if cross(a, b, p) < 0:
        return distance(p, a)
    if cross(b, a, p) < 0:
        return distance(p, b)
    return d

def closest_point_on_segment(p, a, b):
    if a == b:
        return a
    if cross(b, a, p) < 0:
        return a
    if cross(a, b, p) < 0:
        return b
    ax = a[0] - p[0]
    ay = a[1] - p[1]
    bx = b[0] - p[0]
    by = b[1] - p[1]
    t = (ax * ax + ay * ay) / (ax * bx + ay * by)
    t = max(0.0, min(1.0, t))
    return (a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1]))

def closest_point_on_polygon(p, polygon):
    """Find closest point on polygon to point p."""
    n = len(polygon)
    closest = polygon[0]
    min_dist = distance(p, closest)
    for i in range(n):
        a = polygon[i]
        b = polygon[(i + 1) % n]
        proj = closest_point_on_segment(p, a, b)
        d = distance(p, proj)
        if d < min_dist:
            min_dist = d
            closest = proj
    return closest

def compute_half_area(polygon, area_half):
    """Find point on polygon that splits area into two equal halves."""
    n = len(polygon)
    total_area = area(polygon)
    area_half = total_area / 2.0

    # Try all edges
    for i in range(n):
        a = polygon[i]
        b = polygon[(i + 1) % n]
        # Compute area of triangle formed by segment ab
        tri_area = distance(a, b) * distance(a, b) * 0.5
        if tri_area < 1e-9:
            continue

        # Find point on ab that splits area
        # We need to find t such that area of polygon from a to point on ab is area_half
        # Use binary search
        left = 0.0
        right = 1.0
        for _ in range(100):
            t = (left + right) / 2.0
            # Point on ab
            px = a[0] + t * (b[0] - a[0])
            py = a[1] + t * (b[1] - a[1])

            # Compute area of polygon from a to this point
            # This is complex - let's just check if it's equal to half area
            if area([a, b, closest_point_on_polygon((px, py), polygon)]) > area_half:
                left = t
            else:
                right = t

        # Return the point on ab that splits the area
        t = (left + right) / 2.0
        px = a[0] + t * (b[0] - a[0])
        py = a[1] + t * (b[1] - a[1])
        return px, py

