    d = abs((b[0] - a[0]) * (a[1] - p[1]) - (b[1] - a[1]) * (a[0] - p[0]))
    # Check if projection lies on segment
    if cross(a, b, p) < 0:
        return distance(p, a)
    if cross(b, a, p) < 0:
        return distance(p, b)
    return d

