    """Check if point p is inside triangle abc (not on the edges)."""
    d1 = cross(a, b, c)
    d2 = cross(b, c, a)
    d3 = cross(c, a, b)
    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)
    return not (has_neg and has_pos)

