# Read Jiro's cards
jiro_cards = []
for _ in range(n):
    position, strength = input().split()
    jiro_cards.append((int(strength), position))

# Read Ciel's cards
ciel_cards = []
for _ in range(m):
    strength = int(input())
    ciel_cards.append(strength)

# Sort Jiro's cards by strength
jiro_cards.sort()

# Sort Ciel's cards by strength in descending order
ciel_cards.sort(reverse=True)

# Attack strategy:
# 1. Attack DEF cards first
# 2. Then attack ATK cards that can be attacked
# 3. Remaining cards deal direct damage

# For DEF cards:
attack_map = {}
for strength, position in jiro_cards:
    if position == 'DEF':
        attack_map[strength] = attack_map.get(strength, 0) + 1

# Match Ciel's cards to attack DEF cards first
for strength in ciel_cards:
    # Find the weakest DEF card
    for def_strength in attack_map:
        if strength > def_strength:
            attack_map[def_strength] -= 1
            if attack_map[def_strength] == 0:
                del attack_map[def_strength]
            break

# For ATK cards, find which can be attacked
attack_map_atk = {}
for strength, position in jiro_cards:
    if position == 'ATK':
        attack_map_atk[strength] = attack_map_atk.get(strength, 0) + 1

# Match Ciel's cards to attack ATK cards
for strength in ciel_cards:
    # Find the weakest ATK card that can be attacked
    for atk_strength in attack_map_atk:
        if strength >= atk_strength:
            attack_map_atk[atk_strength] -= 1
            if attack_map_atk[atk_strength] == 0:
                del attack_map_atk[atk_strength]
            # Calculate damage
            damage = strength - atk_strength
            print(damage)
            break

# Remaining cards deal direct damage
print(sum(ciel_cards))
