import sys


def solve():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        D_str, E_str = parts[0], parts[1]
        D = int(D_str)
        E = int(E_str)

        if D == 0 and E == 0:
            break

        min_diff = float('inf')

        for x in range(D + 1):
            y = D - x
            distance = math.sqrt(x**2 + y**2)
            diff = abs(distance - E)
            if diff < min_diff:
                min_diff = diff

        print(f"{min_diff:.10f}")

if __name__ == "__main__":
    solve()
"}

