def sieve(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    return is_prime

# Generate primes up to 1,000,000
PRIMES = sieve(1_000_000)

# Create prefix sums
prefix = [0] * len(PRIMES)
count = 0
for i in range(len(PRIMES)):
    if PRIMES[i]:
        count += 1
    prefix[i] = count

# Count primes in range [L, R]
def count_primes_in_range(L, R):
    if L < 0:
        L = 0
    if R > 1_000_000:
        R = 1_000_000
    if L > R:
        return 0
    left = L
    right = R
    # Find first prime >= L
    while left <= right and not PRIMES[left]:
        left += 1
    if left > right:
        return 0
    # Find first prime > R
    while left <= right and PRIMES[left] <= R:
        left += 1
    return left - L

# Main logic
def solve():
    total_charged = 0

    while True:
        n_line = input()
        if not n_line:
            break
        n = int(n_line)
        if n == 0:
            break

        for _ in range(n):
            p, m = map(int, input().split())
            L = p - m
            R = p + m
            x = count_primes_in_range(L, R)

            if x > 0:
                # x primes from lottery sales, x-1 from King's court fees
                total_charged += x - 1
            else:
                # X = 0, 1 prime transferred to court fees from lottery sales
                total_charged += 1

        print(total_charged)

solve()
