import heapq

def solve():
    while True:
        N = int(input())
        if N == 0:
            break

        # Read all tools
        tools = []
        for _ in range(N):
            parts = input().split()
            name = parts[0]
            day1 = int(parts[1])
            sup = parts[2]
            day2 = int(parts[3])
            tools.append((name, day1, sup, day2))

        # Build graph: from tool A to tool B with cost = day2
        graph = {}
        for name, day1, sup, day2 in tools:
            # Add edge: from sup to name with cost = day2
            if sup not in graph:
                graph[sup] = []
            graph[sup].append((name, day2))

        # Dijkstra's algorithm from "no tools"
        # We use a priority queue with (time, tool)

        # Initialize: from "no tools" to each tool via direct path
        dist = {name: day1 for name, day1, _, _ in tools}
        pq = [(day1, name) for name, day1, _, _ in tools]
        heapq.heapify(pq)

        while pq:
            time, tool = heapq.heappop(pq)

            # If we've already found a better path, skip
            if time > dist[tool]:
                continue

            # For each tool that depends on this tool (as support)
            if tool in graph:
                for dependent, support_cost in graph[tool]:
                    new_time = time + support_cost

                    # Use the minimum of: make from scratch (day1) or use support (time + support_cost)
                    if new_time < dist[dependent]:
                        dist[dependent] = new_time
                        heapq.heappush(pq, (new_time, dependent))

        # The answer is the maximum of all min times (we need to complete all tools)
        print(max(dist.values()))

solve()
