{"code": "def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n, m = map(int, input().split())
        k = list(map(int, input().split()))  # 1-indexed
        c = list(map(int, input().split()))

        # We have m presents with costs c[0], c[1], ..., c[m-1]
        # We want to give each friend either a present (from their range) or c_{k_i}

        # We will iterate through friends and try to give them the cheapest available present
        # If we can't give a present (because it's not cheaper than c_{k_i}), we give c_{k_i}

        total = 0
        presents = c.copy()  # list of presents

        for i in range(n):
            if i < len(presents):
                # We can give a present to this friend
                if k[i] > 1:
                    # Find the cheapest present in their range
                    min_present = min(presents[:k[i]-1])
                    if min_present < c[k[i]-1]:
                        # Give the cheapest present in their range
                        total += min_present
                        # Remove that present from available
                        presents.remove(min_present)
                    else:
                        # Give c_{k_i} dollars
                        total += c[k[i]-1]
                else:
                    # k[i] == 1, only option is c_1
                    total += c[0]
            else:
                # No presents left, give c_{k_i} dollars
                total += c[k[i]-1]

        results.append(str(total))

    print("\n".join(results))

