import sys

def solve() -> None:
    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)

    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    t = int(next(it))

    # Read waste cells
    waste = set()
    for _ in range(k):
        a = int(next(it))
        b = int(next(it))
        waste.add((a, b))

    # Process queries
    out = []
    for _ in range(t):
        i = int(next(it))
        j = int(next(it))

        if (i, j) in waste:
            out.append("Waste")
        else:
            # Count how many cultivated cells come before this one in row-major order
            count = 0

            # Cells in previous rows
            for row in range(1, i):
                count += m

            # Cells in same row before current column
            count += j - 1

            # Skip waste cells in previous rows
            for row in range(1, i):
                for col in range(1, m + 1):
                    if (row, col) not in waste:
                        count += 1

            # Skip waste cells in current row up to current column
            for col in range(1, j):
                if (i, col) not in waste:
                    count += 1

            # Determine crop
            mod = count % 3
            if mod == 0:
                out.append("Carrots")
            elif mod == 1:
                out.append("Kiwis")
            else:
                out.append("Grapes")

    print("\n".join(out))

if __name__ == "__main__":
    solve()
