# Store the count of each number
count = {}
for num in a:
    count[num] = count.get(num, 0) + 1

# Store which numbers are still available
available = set(count.keys())

# Find which elements cannot be paired
unpaired = []

# Check each number
for num in list(available):
    # This number needs to be paired with another
    if count[num] == 0:
        continue

    found_pair = False

    # Check all powers of two
    for power in [1 << d for d in range(1, 31)]:  # 2^d from 2^1 to 2^30
        target = power - num

        # Check if target exists and we have at least one
        if target in available and count[target] > 0:
            # If target is the same number, we need at least 2 of them
            if target == num:
                if count[num] >= 2:
                    found_pair = True
            else:
                found_pair = True

            # Mark both as used
            if target in available:
                available.remove(target)
            if num in available:
                available.remove(num)

            break

    if not found_pair:
        # No pair found, mark this number for removal
        unpaired.append(num)

# The answer is the number of elements that need to be removed
print(len(a) - len(available))
