def combination(n, k, mod):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n - k:
        k = n - k
    res = 1
    for i in range(k):
        res = res * (n - i) % mod
    for i in range(1, k + 1):
        res = res * pow(i, mod - 2, mod) % mod
    return res

T = int(input())
mod = 10**9 + 7
for _ in range(T):
    N, M = map(int, input().split())
    if M % 2 != 0 or M < 4:
        print(0)
        continue
    k = M // 2

    # We need to choose i Red Face, (k - i) Red Rank, (k - i) Black Face, i Black Rank
    # So we need: i <= 6N, k - i <= 18N, k - i <= 6N, i <= 18N
    max_i = min(k, 6 * N)

    ans = 0
    for i in range(0, max_i + 1):
        # Check if we can choose this many of each type
        if k - i <= 6 * N and i <= 18 * N:
            c1 = combination(6 * N, i, mod)
            c2 = combination(18 * N, k - i, mod)
            c3 = combination(6 * N, k - i, mod)
            c4 = combination(18 * N, i, mod)
            ans = (ans + c1 * c2 * c3 * c4) % mod

    print(ans)
