import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    Q = int(next(it))
    cards = [int(next(it)) for _ in range(N)]

    # Sort cards
    cards.sort()

    # Precompute remainders for all possible values up to max card value
    # This is too memory-intensive

    # Instead, use binary search to find the largest card less than q
    # and the smallest card >= q

    for _ in range(Q):
        q = int(next(it))
        max_rem = 0

        # Binary search to find largest card less than q
        left, right = 0, N
        while left < right:
            mid = (left + right) // 2
            if cards[mid] < q:
                left = mid + 1
            else:
                right = mid
        if left > 0:
            max_rem = cards[left - 1]

        # Binary search to find smallest card >= q
        left, right = 0, N
        while left < right:
            mid = (left + right) // 2
            if cards[mid] >= q:
                right = mid
            else:
                left = mid + 1
        if left < N:
            max_rem = max(max_rem, cards[left] - q)

        print(max_rem)

if __name__ == "__main__":
    solve()
"}

