import math

def solve(a, b, p):
    if b == 0:
        return 0.0

    # Handle negative values
    a_abs = abs(a)
    b_abs = abs(b)

    # Area at val is: (1/2) * (ab - 2a val + a val^2 / b)
    # But we need to be careful with signs

    # Use quadratic formula
    A = a / b
    B = -2 * a
    C = a * b - 2 * (p / 100) * a_abs * b_abs

    discriminant = B**2 - 4 * A * C

    if discriminant < 0:
        # No solution, area is always greater than target
        return float('inf')

    sqrt_discriminant = math.sqrt(discriminant)
    val = (-B - sqrt_discriminant) / (2 * A)

    # Adjust for orientation
    # For standard orientation (both positive), val should be positive and less than b
    if a > 0 and b > 0:
        return max(0.0, min(val, b))
    elif a < 0 and b > 0:
        # Triangle below origin on y-axis
        return max(0.0, b)
    elif a > 0 and b < 0:
        # Triangle to the left of origin on x-axis
        return max(0.0, b)
    else:
        # Both negative
        return max(0.0, b)

# Read input
a, b, p = map(int, input().split())

# Solve and print with 2 decimal places
result = solve(a, b, p)
print(f"{result:.2f}")
"}

