import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        a, b, c, d = map(int, sys.stdin.readline().split())
        x = b  # maximum in [a, b]
        y = c  # maximum in [b, c]
        z = min(d, x + y - 1)  # ensure x + y > z
        print(x, y, z)

if __name__ == "__main__":
    solve()
"}

