import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    s = data[0]
    m = int(data[1])

    # Create a list of positions for each character
    char_positions = {}  # maps each character to a list of its positions

    for i, ch in enumerate(s):
        if ch not in char_positions:
            char_positions[ch] = []
        char_positions[ch].append(i)

    # Now process queries
    for i in range(2, 2 + 2 * m, 2):
        K = int(data[i])
        x = data[i + 1]

        # Find the K-th occurrence of x
        if x in char_positions and len(char_positions[x]) >= K:
            pos = char_positions[x][K-1]

            # Remove the character at position pos
            s = s[:pos] + s[pos+1:]

            # Update all character positions after pos
            for ch in char_positions:
                positions = char_positions[ch]
                for j in range(len(positions)):
                    if positions[j] > pos:
                        positions[j] -= 1

    print(s)

if __name__ == "__main__":
