import sys
import math

def is_primitive_pythagorean_triplet(a, b, c):
    # Check if the numbers satisfy Pythagorean theorem
    if a > b:
        a, b = b, a
    if a > c:
        a, c = c, a
    if b > c:
        b, c = c, b

    # Now a <= b <= c, check if a² + b² = c²
    if a * a + b * b != c * c:
        return False

    # Check if they are coprime (gcd of all three is 1)
    # We can check gcd of all three numbers
    return math.gcd(math.gcd(a, b), c) == 1


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    T = int(data[idx])
    idx += 1

    results = []

    for _ in range(T):
        a = int(data[idx])
        b = int(data[idx + 1])
        c = int(data[idx + 2])
        idx += 3

        if is_primitive_pythagorean_triplet(a, b, c):
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    main()
