# Read input
N = int(input())
strings = [input().strip() for _ in range(N)]
t = input().strip()

# Create a map from position in t to list of lengths of strings that match starting at that position
prefix_map = {}

for s in strings:
    len_s = len(s)
    # For each position where s can match
    for i in range(len(t) - len_s + 1):
        if t[i:i+len_s] == s:
            if i not in prefix_map:
                prefix_map[i] = []
            prefix_map[i].append(len_s)

# Dynamic programming
# dp[i] = number of ways to split first i characters of t
len_t = len(t)
dp = [0] * (len_t + 1)
dp[0] = 1  # 1 way to split empty string

for i in range(len_t + 1):
    if i in prefix_map:
        for length in prefix_map[i]:
            dp[i + length] = (dp[i + length] + dp[i]) % MOD

print(dp[len_t])
