import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    T = int(data[0])
    out_lines = []
    for i in range(1, T+1):
        expr = data[i].strip()
        tokens = []
        j = 0
        while j < len(expr):
            if expr[j].isdigit():
                num = ''
                while j < len(expr) and expr[j].isdigit():
                    num += expr[j]
                    j += 1
                tokens.append(int(num))
            else:
                tokens.append(expr[j])
                j += 1
        # Reverse to evaluate right to left
        tokens.reverse()
        # Now process left to right
        res = tokens[0]
        op_index = 1
        while op_index < len(tokens):
            op = tokens[op_index]
            right = tokens[op_index + 1]
            if op == '+':
                res += right
            elif op == '-':
                res -= right
            elif op == '*':
                res *= right
            op_index += 2
        out_lines.append(str(res))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
