                while j < len(expr) and expr[j].isdigit():
                    num += expr[j]
                    j += 1
                tokens.append(int(num))
            else:
                tokens.append(expr[j])
                j += 1
        # Reverse to evaluate right to left
        tokens.reverse()
        # Now process left to right
        res = tokens[0]
        op_index = 1
        while op_index < len(tokens):
            op = tokens[op_index]
            right = tokens[op_index + 1]
            if op == '+':
                res += right
            elif op == '-':
                res -= right
            elif op == '*':
                res *= right
            op_index += 2
        out_lines.append(str(res))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
"}

