def dijkstra(n, adj, start):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    import heapq
    heap = [(0, start)]

    while heap:
        time, node = heapq.heappop(heap)

        if time > dist[node]:
            continue

        for neighbor, travel_time in adj[node]:
            if dist[neighbor] > time + travel_time:
                dist[neighbor] = time + travel_time
                heapq.heappush(heap, (dist[neighbor], neighbor))

    return dist

def solve():
    T = int(input())

    for _ in range(T):
        N, M = map(int, input().split())

        adj = [[] for _ in range(N + 1)]

        for _ in range(M):
            X, Y, C = map(int, input().split())
            adj[X].append((Y, C))
            adj[Y].append((X, C))

        S, A, H = map(int, input().split())

        # Compute shortest distances from S, A, H
        dist_S = dijkstra(N, adj, S)
        dist_A = dijkstra(N, adj, A)
        dist_H = dijkstra(N, adj, H)

        max_time = 0

        for b in range(1, N + 1):
            if b == S or b == A or b == H:
                continue

            time = dist_S[b] + 2 * dist_A[b] + dist_H[b]
            if time > max_time:
                max_time = time

        print(max_time)

solve()
