L = len(t)

# Build a map from lengths to set of strings
def get_substrings_at(i):
    result = set()
    for s in strings:
        if i + len(s) > L:
            continue
        if t[i:i+len(s)] == s:
            result.add(i + len(s))
    return result

# Dynamic programming approach
from collections import defaultdict
dp = [0] * (L + 1)
dp[0] = 1

for i in range(L):
    for pos in get_substrings_at(i):
        dp[pos] = (dp[pos] + dp[i]) % MOD

print(dp[L] % MOD)
