import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    a = list(map(int, data[2:2+n]))
    b = list(map(int, data[2+n:2+2*n]))

    # For each element a_i, compute all possible x values
    possible_x = set(range(m))

    for i in range(n):
        ai = a[i]
        for j in range(n):
            diff = (b[j] - ai) % m
            # Only keep the intersection of all sets
            possible_x &= {diff}

    # Find the smallest non-negative x in possible_x
    if possible_x:
        print(min(possible_x))
    else:
        print(0)

if __name__ == "__main__":
    solve()
"}

