                                queue.append(new_pos)
                    break
        return False

    # Check if we can reach the leftmost trampoline from the rightmost
    def can_reach_left(pos):
        visited = [False] * (n * 10 + 1)
        queue = deque()
        queue.append(pos)
        visited[pos] = True

        while queue:
            current = queue.popleft()
            if current <= 0:
