def discrete_jumps(n, h):
    stack = []

    # For each starting position i
    for i in range(n):
        if i == n - 1:
            # We are at the last skyscraper
            return len(stack) + 1

        l = i + 1
        r = n - 1

        # For each position we can jump to from i
        for j in range(i + 1, n):
            # Check if we can jump from i to j
            is_discrete = True

            # Check if segment [i+1, j-1] is completely below both endpoints or completely above both endpoints
            if i + 1 < j - 1:
                # Segment has at least one element
                min_between = min(h[i+1:j])
                max_between = max(h[i+1:j])

                # Check if segment is completely below both endpoints
                if max_between < min(h[i], h[j]):
                    pass
                # Check if segment is completely above both endpoints
                elif max(h[i], h[j]) < min_between:
                    pass
                else:
                    is_discrete = False
            else:
                # Segment is empty (adjacent skyscrapers)
                is_discrete = True

            if is_discrete:
                stack.append((i, j))

    return len(stack)

# Read input
