def process_ball(state):
    """Simulate one ball passing through the devices"""
    n = len(state)

    # Ball enters device 1 from left
    pos = 0  # Index of current device, starting at device 1
    direction = 0  # 0 for left to right, 1 for right to left

    while True:
        # Ball moves according to current device's state
        if state[pos] == 'A':
            # State A: ball throws from same side (same direction)
            # Ball was coming from left, goes to right
            if direction == 0:
                if pos + 1 < n:
                    pos += 1
                else:
                    break  # Ball exits from right
            else:
                if pos - 1 >= 0:
                    pos -= 1
                else:
                    break  # Ball exits from left
            # Switch to state B
