def polygon_area(points):
    """Compute the area of a convex polygon using the shoelace formula"""
    area = 0.0
    n = len(points)
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i+1)%n]
        area += (x1 * y2) - (x2 * y1)
    return abs(area) / 2.0

def cross(o, a, b):
    """Cross product of vectors OA and OB"""
    return (a[0] - o[0])*(b[1] - o[1]) - (a[1] - o[1])*(b[0] - o[0])

def point_segment_intersection(o, a, b, p):
    """Check if point p lies on segment ab"""
    if cross(o, a, b) == 0:
        # Collinear
        return abs(min(a[0], b[0]) - max(o[0], p[0])) < 1e-9 and \n               abs(min(a[1], b[1]) - max(o[1], p[1])) < 1e-9
    # Check if p is on the segment
    if cross(o, a, p) * cross(o, b, p) > 0:
        return False
    return True

def find_equal_area_line(points, vertex_idx, edge_idx, area):
    """Find a line passing through vertex v that splits the polygon into two parts with area = target_area"""
    n = len(points)
    v = points[vertex_idx]
    # Determine the opposite edge
    if edge_idx == n - 1:
        edge_idx = 0
    elif edge_idx == 0:
        edge_idx = n - 1
    w1 = points[edge_idx]
    w2 = points[(edge_idx + 1) % n]

    # Find direction vector of the opposite edge
    dir1 = (w2[0] - w1[0], w2[1] - w1[1])
    dir2 = (-dir1[0], -dir1[1])

    # Check if line through v and w1 splits the area
    left_area = 0.0
    for i in range(n):
        if i == vertex_idx:
            continue
        if i == edge_idx:
            continue
        elif i == (edge_idx + 1) % n:
            continue
        left_area += cross(v, points[i], points[(i+1)%n])
    left_area = abs(left_area) / 2.0

    if abs(left_area - area) < 1e-9:
        return (v, points[(edge_idx + 1) % n])

    # Move along the opposite edge
    t = 0.0
    step = 0.001
    for _ in range(5000):
        p = (w1[0] + t * dir1[0], w1[1] + t * dir1[1])
        left_area = 0.0
        for i in range(n):
            if i == vertex_idx:
                continue
            elif i == edge_idx:
                continue
            elif i == (edge_idx + 1) % n:
                continue
            left_area += cross(v, points[i], points[(i+1)%n])
        left_area = abs(left_area) / 2.0

        if left_area < area:
            t += step
        elif left_area > area:
            t -= step
        else:
            t = 0.0
            break

    return (v, (w1[0] + t * dir1[0], w1[1] + t * dir1[1]))

def compute_min_max_segments(points):
    n = len(points)
    total_area = polygon_area(points)
    target_area = total_area / 2.0

    min_len = float('inf')
    max_len = 0.0

    # Try all combinations of two vertices
    for i in range(n):
        for j in range(i+1, n):
            # Check if this segment splits the polygon into two equal areas
            left_area = 0.0
            for k in range(n):
                if k == i or k == j:
