def sieve(limit):
    """Generate list of primes up to limit using Sieve of Eratosthenes."""
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    return [i for i, prime in enumerate(is_prime) if prime]

def main():
    primes = sieve(999983)  # Generate all known primes up to 999983

    while True:
        n = int(input())
        if n == 0:
            break

        total_court_fees = 0

        for _ in range(n):
            p, m = map(int, input().split())
            # Count primes in range [p-m, p+m]
            count = 0
            for prime in primes:
                if p - m <= prime <= p + m:
                    count += 1
                elif prime > p + m:
                    break

            # Calculate court fees
            if count > 0:
                total_court_fees += count - 1  # X-1 prime from court fees
            elif count == 0:
                # If no primes in range, 1 prime will be transferred to court fees from lottery sales
                total_court_fees += 1

        print(total_court_fees)

if __name__ == "__main__":
    main()
