import math
import sys

def solve():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        D = int(parts[0])
        E = int(parts[1])
        if D == 0 and E == 0:
            break

        min_diff = float('inf')
        # Generate all integer pairs (x, y) such that x + y = D
        for x in range(D + 1):
            y = D - x
            # Calculate Euclidean distance
            distance = math.sqrt(x**2 + y**2)
            # Calculate absolute difference from budget E
            diff = abs(distance - E)
            if diff < min_diff:
                min_diff = diff

        print(f"{min_diff:.10f}")

if __name__ == '__main__':
    solve()
