def get_crop_position(position):
    mod = position % 3
    if mod == 0:
        return "Carrots"
    elif mod == 1:
        return "Kiwis"
    else:
        return "Grapes"

# Read input
import sys
lines = sys.stdin.read().splitlines()

index = 0
n, m, k, t = map(int, lines[index].split())
index += 1

waste_cells = set()
for _ in range(k):
    a, b = map(int, lines[index].split())
    waste_cells.add((a, b))
    index += 1

for _ in range(t):
    i, j = map(int, lines[index].split())
    index += 1

    if (i, j) in waste_cells:
        print("Waste")
    else:
        # Count cultivated cells before (i, j)
        count = 0

        # Iterate through all cells
        for row in range(1, n + 1):
            for col in range(1, m + 1):
                if row == i and col == j:
                    break
                if (row, col) not in waste_cells:
                    count += 1

        crop = get_crop_position(count + 1)
        print(crop)
