n, t = map(int, input().split())
balls = []

for _ in range(n):
    xi, vi, mi = map(int, input().split())
    balls.append((xi, vi, mi))

# Since we have at most 10 balls and t ≤ 100,
# we can simulate with a very small time step

time_step = 0.001

collision_occurred = False
for step in range(int(t / time_step)):
    # Update positions
    for i in range(n):
        balls[i] = (balls[i][0] + balls[i][1] * time_step, 
                   balls[i][1], balls[i][2])

    # Check for collisions
    for i in range(n):
        for j in range(i + 1, n):
            # If they're at the same position, they collide
            if abs(balls[i][0] - balls[j][0]) < 1e-9:
                # Swap velocities if masses are equal
                if balls[i][2] == balls[j][2]:
                    balls[i] = (balls[i][0], balls[j][1], balls[i][2])
                    balls[j] = (balls[j][0], balls[i][1], balls[j][2])

                # Since we found a collision, we'll simulate the remaining time
                # by just using the new velocities
                collision_occurred = True
                break
        if collision_occurred:
            break

# If we had a collision, we need to calculate the remaining time
if collision_occurred:
    for i in range(n):
        balls[i] = (balls[i][0] + balls[i][1] * (t - (step + 1) * time_step),
                   balls[i][1], balls[i][2])

# Output final positions
for x, _, _ in balls:
    print(f"{x:.10f}")
"}

