def prime_factors(n):
    """Return a list of tuples (prime, exponent) for n."""
    prime_factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            prime_factors[i] = prime_factors.get(i, 0) + 1
            n //= i
        i += 1
    if n > 1:
        prime_factors[n] = prime_factors.get(n, 0) + 1
    return prime_factors

def count_prime_in_factorial(m, p):
    """Count how many times prime p divides m!"""
    count = 0
    power = p
    while power <= m:
        count += m // power
        power *= p
    return count

