{"code": "N, A, B, C = map(int, input().split())
lengths = [int(input()) for _ in range(N)]

min_mp = float('inf')

for kA in range(1, N+1):
    for kB in range(1, N - kA + 1):
        kC = N - kA - kB
        if kC < 1:
            continue

        from itertools import combinations

        # Try all combinations of which bamboos go to which target
        for a_indices in combinations(range(N), kA):
            remaining = [i for i in range(N) if i not in a_indices]

            for b_indices in combinations(remaining, kB):
                c_indices = [i for i in range(N) if i not in a_indices and i not in b_indices]

                # Calculate costs
                cost = 0
                for i in a_indices:
                    cost += abs(lengths[i] - A)
                for i in b_indices:
                    cost += abs(lengths[i] - B)
                for i in c_indices:
                    cost += abs(lengths[i] - C)

                # Combine costs
                cost += 10 * (kA - 1)  # A
                cost += 10 * (kB - 1)  # B
                cost += 10 * (kC - 1)  # C

                min_mp = min(min_mp, cost)

print(min_mp)
"}

{"code": "n, m, k, t = map(int, input().split())

waste_set = set()
waste_per_row = [0] * (n + 1)

for _ in range(k):
    a, b = map(int, input().split())
    waste_set.add((a, b))
    waste_per_row[a] += 1

# Precompute prefix sums for waste in columns for each row
# waste_col_prefix[i][j] = number of waste cells in row i with column <= j
waste_col_prefix = [{} for _ in range(n + 1)]

for _ in range(k):
    a, b = map(int, input().split())
    row = a
    col = b
    waste_set.add((a, b))
    waste_per_row[a] += 1

    # Add to prefix sum for row a
    if row not in waste_col_prefix:
        waste_col_prefix[row] = {}

    # For each column, maintain the cumulative waste
    if col not in waste_col_prefix[row]:
        waste_col_prefix[row][col] = 0
    waste_col_prefix[row][col] = waste_col_prefix[row][col - 1] + 1

for _ in range(t):
    i, j = map(int, input().split())
    if (i, j) in waste_set:
        print("Waste")
    else:
        # Count cultivated cells before (i, j)
        count = (i-1) * m + (j-1)

        # Subtract waste cells before row i
        for row in range(1, i):
            count -= waste_per_row[row]

        # Subtract waste cells in row i before column j
        if i in waste_col_prefix:
            # Find the cumulative waste in row i with column <= j-1
            if (j-1) in waste_col_prefix[i]:
                count -= waste_col_prefix[i][j-1]
            else:
                # If j-1 not in prefix, it means no waste with column <= j-1
                pass

        # Determine the plant type
        remainder = count % 3
        if remainder == 0:
            print("Carrots")
        elif remainder == 1:
            print("Kiwis")
        else:  # remainder == 2
            print("Grapes")
