def solve():
    n = int(input())
    a = list(map(int, input().split()))
    m = int(input())
    b = list(map(int, input().split()))

    # Calculate prefix sums
    prefix_a = [0] * (n + 1)
    for i in range(n):
        prefix_a[i + 1] = prefix_a[i] + a[i]

    prefix_b = [0] * (m + 1)
    for i in range(m):
        prefix_b[i + 1] = prefix_b[i] + b[i]

    # Find the longest common prefix sequence
    i, j = 0, 0
    common_len = 0

    while i < n and j < m:
        if prefix_a[i + 1] == prefix_b[j + 1]:
            common_len += 1
            i += 1
            j += 1
        else:
            # If they don't match, we need to merge
            if prefix_a[i + 1] < prefix_b[j + 1]:
                # Merge in A
                i += 1
            else:
                # Merge in B
                j += 1

    # Check if we can form the same array from both sides
    if i == n and j == m:
        # Now we need to ensure we can form the same array
        # Check if we can match the remaining
        i, j = 0, 0
        match = True

        while i < n and j < m:
            if prefix_a[i + 1] == prefix_b[j + 1]:
                i += 1
                j += 1
            else:
                match = False
                break

        if match:
            print(common_len)
        else:
            print(-1)
    else:
        print(-1)

