def longest_palindromic_subsequence_length(s, start, end):
    """Return the length of the longest palindromic subsequence in s[start..end]"""
    if start > end:
        return 0
    if start == end:
        return 1

    # If first and last characters match
    if s[start] == s[end]:
        return 2 + longest_palindromic_subsequence_length(s, start + 1, end - 1)

    # Otherwise, take max of either excluding start or excluding end
    return max(
        longest_palindromic_subsequence_length(s, start + 1, end),
        longest_palindromic_subsequence_length(s, start, end - 1)
    )

# Read input
n = int(input())
strings = []
for _ in range(n):
    strings.append(input().strip())

# Process each string
for s in strings:
    lps_length = longest_palindromic_subsequence_length(s, 0, len(s) - 1)
    min_insertions = len(s) - lps_length
    print(min_insertions)
