def max_value(n, memo):
    if n <= 4:
        return n
    if n in memo:
        return memo[n]

    # Calculate the maximum value by exchanging
    exchange_value = max_value(n//2, memo) + max_value(n//3, memo) + max_value(n//4, memo)

    # Return the maximum of exchanging or selling directly
    memo[n] = max(n, exchange_value)
    return memo[n]

